"""hands' models must match lib/contracts (generated by tools/schemas.py)."""

from __future__ import annotations

import json
from pathlib import Path

import jsonschema

from zpkt.live import schemas
from zpkt.live.library.models import Inventory, StepScore, TrackReport
from zpkt.live.models import ProjectConfig

ROOT = Path(__file__).resolve().parents[2]


def test_committed_schemas_are_current() -> None:
    for name, model in schemas.MODELS.items():
        committed = json.loads((ROOT / "lib" / "contracts" / f"{name}.schema.json").read_text())
        assert committed == schemas.build(name, model), (
            f"stale {name} contract: run `uv run python -m zpkt.live.schemas`"
        )


def test_instances_validate() -> None:
    pc = json.loads(ProjectConfig(name="t").model_dump_json())
    jsonschema.validate(pc, schemas.build("project-config", ProjectConfig))
    inv = Inventory(
        generated="2026-10-10T00:00:00+00:00",
        roots=["/lib"],
        tracks=[
            TrackReport(
                track="HW1", steps=[StepScore(step="mix", numeral="V", percent=40, heuristic=40, evidence=["2 groups"])]
            )
        ],
    )
    jsonschema.validate(json.loads(inv.model_dump_json()), schemas.build("inventory", Inventory))
